const e = $json;
const feed = $('Build Feed List').item.json;
const clip = (s,n)=>{ s=(s==null?'':String(s)); return s.length>n?s.slice(0,n):s; };
let cats='';
if (Array.isArray(e.categories)) cats = e.categories.map(c => (c&&typeof c==='object')?(c.name||c._||c.term||''):c).filter(Boolean).join(', ');
else if (e.categories) cats = String(e.categories);
const content = e['content:encoded'] || e.content || e.contentSnippet || e.summary || e.description || '';
return { json: {
  guid: clip(e.guid || e.id || e.link || (feed.source+'|'+(e.title||'')), 480),
  source: feed.source || '',
  title: clip(e.title || '(no title)', 1000),
  link: e.link || e.id || '',
  author: clip(e.creator || e.author || e['dc:creator'] || '', 300),
  pubDate: e.isoDate || e.pubDate || '',
  categories: clip(cats, 1000),
  summary: clip(e.contentSnippet || e.summary || e.description || '', 2000),
  content: clip(content, 10000),
  ingestedAt: new Date().toISOString()
} };

const posts = $input.all().map(i=>i.json);
const DAYS = 14, CAP = 25;
const INC = ["grc","governance","compliance","regulat","audit","policy","framework","cmmc","nist","soc 2","soc2",
"fedramp","iso 27001","iso 42001","hipaa","pci dss"," pci ","gdpr","ccpa","cpra","ai act","dora","sox",
"sarbanes","fisma"," rmf ","privacy","whistleblow","ethics","third-party risk","third party risk","tprm",
"vendor risk","internal investigation"," sec "," doj "," ftc ","executive order","disclosure","attestation",
"certification","controls","data breach","breach","data protection","information security","infosec","ciso",
"fraud","sanction","export control","esg","zero trust","supply chain","post-quantum","risk management",
"data governance","cyber insurance","ransomware","incident response"];
const cutoff = $now.toMillis() - DAYS*86400000;
const ts = s => { if(!s) return null; const t=Date.parse(s); return isNaN(t)?null:t; };
// L1 recency (keep undated)
let l1 = posts.filter(p => { const t=ts(p.pubDate); return t===null || t>=cutoff; });
// L2 per-feed cap (newest first)
l1.sort((a,b)=> (ts(b.pubDate)||cutoff) - (ts(a.pubDate)||cutoff));
const byf = {};
l1.forEach(p => { (byf[p.source]=byf[p.source]||[]).push(p); });
let l2 = [];
Object.keys(byf).forEach(s => { l2 = l2.concat(byf[s].slice(0, CAP)); });
// L3 GRC + governance relevance
const rel = p => {
  const hay = (' '+(p.title||'')+' '+(p.summary||'')+' '+(p.categories||'')+' ').toLowerCase();
  return INC.some(t => hay.includes(t));
};
const l3 = l2.filter(rel);
return l3.map(p => ({ json: { source:p.source, title:p.title, link:p.link, pubDate:p.pubDate,
  categories:p.categories, summary:p.summary, guid:p.guid } }));

const items = $input.all().map(i=>i.json);
const lines = items.map((p,idx)=> idx+'. ['+(p.source||'')+'] '+(p.title||'')+((p.summary)?(' — '+String(p.summary).replace(/\s+/g,' ').slice(0,120)):''));
return [{ json: { prompt: lines.join('\n'), count: items.length } }];

