const items = $('Filter Shortlist').all().map(i=>i.json);
const cmap = {};
$('Normalize').all().forEach(o => { const j=o.json; if (j && j.guid) cmap[j.guid] = {content:j.content, summary:j.summary, author:j.author, categories:j.categories}; });
let parsed = $json.output || $json; if (parsed && parsed.output) parsed = parsed.output;
const scores = (parsed && parsed.scores) || [];
const byI = {}; scores.forEach(s => { if (s && s.i!=null) byI[s.i]=s; });
const scored = items.map((p,idx) => { const s=byI[idx]||{}; const cc=cmap[p.guid]||{}; return {
  source:p.source, title:p.title, link:p.link, pubDate:p.pubDate, guid:p.guid,
  marketDriverScore:(typeof s.marketDriverScore==='number')?s.marketDriverScore:0,
  driverType:s.driverType||'off-topic', clientRelevance:s.clientRelevance||'none',
  blogAngle:s.blogAngle||'', keep:!!s.keep, topicKey:(s.topicKey||'').toString().toLowerCase().trim(),
  content:cc.content||'', summary:cc.summary||p.summary||'' }; });
let kept = scored.filter(m => m.keep && m.driverType!=='off-topic');
const norm = t => (t||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>3).slice(0,7).join(' ');
kept.sort((a,b)=> b.marketDriverScore - a.marketDriverScore);
const groups = {};
kept.forEach(m => { const key = m.topicKey || norm(m.title); (groups[key]=groups[key]||[]).push(m); });
const slate = Object.values(groups).map(g => { g.sort((a,b)=>b.marketDriverScore-a.marketDriverScore);
  const rep = Object.assign({}, g[0]); rep.alsoCoveredBy = g.slice(1).map(x=>x.source); rep.dupeCount=g.length; return rep; })
  .sort((a,b)=> b.marketDriverScore - a.marketDriverScore).slice(0,20);
return slate.map(m => ({ json: m }));

const rows = $input.all().map(i=>i.json);
const esc = s => String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const weekLabel = $now.toFormat('LLL d, yyyy');
const band = s => s>=85?'#b91c1c':(s>=70?'#b45309':(s>=40?'#475569':'#94a3b8'));
const paras = s => String(s||'').split(/\n\s*\n/).map(p=>p.trim()).filter(Boolean)
  .map(p=>'<p style="margin:0 0 10px;">'+esc(p)+'</p>').join('') || '<p style="color:#64748b;">No summary.</p>';
const index = rows.map((r,i)=>
  '<tr><td style="padding:6px 8px;border-top:1px solid #f1f5f9;color:#64748b;font-size:13px;">'+(i+1)+'</td>'+
  '<td style="padding:6px 8px;border-top:1px solid #f1f5f9;"><span style="font-weight:800;color:'+band(r.marketDriverScore)+';">'+r.marketDriverScore+'</span></td>'+
  '<td style="padding:6px 8px;border-top:1px solid #f1f5f9;font-size:13px;"><a href="#a'+i+'" style="color:#0f172a;text-decoration:none;font-weight:600;">'+esc(r.title)+'</a>'+
  '<div style="color:#64748b;font-size:11px;">'+esc(r.driverType)+' · '+esc(r.clientRelevance)+'</div></td></tr>').join('');
const cards = rows.map((r,i)=>{
  const also = (r.alsoCoveredBy && r.alsoCoveredBy.length)? '<div style="color:#cbd5e1;font-size:12px;margin-top:4px;">Also covered by: '+r.alsoCoveredBy.map(esc).join(', ')+'</div>':'';
  return '<div id="a'+i+'" style="border:1px solid #e2e8f0;border-radius:12px;margin:0 0 16px;overflow:hidden;background:#fff;">'+
    '<div style="background:#0f172a;padding:14px 18px;">'+
      '<div style="color:#93c5fd;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;">#'+(i+1)+' · '+esc(r.driverType)+' · '+esc(r.clientRelevance)+'</div>'+
      '<div style="margin-top:4px;font-size:17px;font-weight:800;color:#fff;">'+esc(r.title)+'</div>'+
      '<div style="color:#cbd5e1;font-size:12px;margin-top:4px;">'+esc(r.source)+' · '+esc(String(r.pubDate||'').slice(0,10))+' · score <b style="color:#fff;">'+r.marketDriverScore+'</b></div>'+also+
    '</div>'+
    '<div style="background:#eff6ff;border-bottom:1px solid #dbeafe;padding:10px 18px;font-size:13px;color:#1e3a8a;"><b>Blog angle:</b> '+esc(r.blogAngle)+'</div>'+
    '<div style="padding:14px 18px;font-size:14px;line-height:1.6;color:#1f2937;">'+paras(r.summary2)+
      '<div style="margin-top:8px;"><a href="'+esc(r.link)+'" style="color:#2563eb;text-decoration:none;font-weight:600;">Read the full article &rarr;</a></div></div></div>';
}).join('');
const subject = '[TEST] GRC Market-Driver Slate — '+weekLabel+' — '+rows.length+' topics';
const html =
'<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;max-width:760px;margin:0 auto;background:#f8fafc;padding:24px;color:#0f172a;">'+
 '<div style="background:#0f172a;border-radius:14px;padding:24px 28px;margin-bottom:18px;">'+
  '<div style="color:#93c5fd;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;">Lazarus Alliance · Content Radar</div>'+
  '<div style="color:#fff;font-size:22px;font-weight:800;margin-top:6px;">Weekly GRC Market-Driver Slate</div>'+
  '<div style="color:#cbd5e1;font-size:13px;margin-top:4px;">Week of '+esc(weekLabel)+' · '+rows.length+' ranked topics · sourced from 10 industry feeds</div></div>'+
 '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:14px 18px;margin-bottom:18px;font-size:14px;color:#1e3a8a;line-height:1.5;">&#128221; <b>Want a draft?</b> Open the <a href="https://lazarusalliance.app.n8n.cloud/webhook/grc-content-studio/chat" style="color:#2563eb;font-weight:700;text-decoration:none;">GRC Content Studio</a> and just tell it a topic number below &mdash; it researches the topic and drafts a blog post + LinkedIn post for you.</div>'+
 '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:8px 18px 14px;margin-bottom:18px;">'+
  '<div style="font-size:13px;font-weight:800;text-transform:uppercase;color:#475569;letter-spacing:.04em;padding:12px 0 4px;">Ranked topics</div>'+
  '<table role="presentation" width="100%" style="border-collapse:collapse;"><tr><td style="font-size:11px;color:#94a3b8;padding:0 8px;">#</td><td style="font-size:11px;color:#94a3b8;padding:0 8px;">Score</td><td style="font-size:11px;color:#94a3b8;padding:0 8px;">Topic</td></tr>'+index+'</table></div>'+
 cards+
 '<div style="font-size:11px;color:#94a3b8;line-height:1.6;padding-top:8px;border-top:1px solid #e2e8f0;">Scored by Claude for market-driving relevance; duplicate stories merged by topic. 2-paragraph summaries; full article text retained in the content catalog. Source: Lazarus Alliance Content Radar (Workflow A).</div>'+
'</div>';
return [{ json: { subject, html, total: rows.length } }];

const items = $input.all().map(i=>i.json);
const strip = s => String(s||'').replace(/<[^>]+>/g,' ').replace(/&[a-z]+;/g,' ').replace(/\s+/g,' ').trim();
const lines = items.map((p,idx)=>{
  const body = strip(p.content) || strip(p.summary) || '(no article body available)';
  return 'ITEM '+idx+':
TITLE: '+(p.title||'')+'
SOURCE: '+(p.source||'')+'
ARTICLE: '+body.slice(0,3500);
});
return [{ json: { prompt: lines.join('

---

'), count: items.length } }];

const slate = $('Rank & Slate').all().map(i=>i.json);
let parsed = $json.output || $json; if (parsed && parsed.output) parsed = parsed.output;
const sums = (parsed && parsed.summaries) || [];
const byI = {}; sums.forEach(s => { if (s && s.i!=null) byI[s.i] = s.summary; });
return slate.map((m,idx) => ({ json: Object.assign({}, m, { summary2: byI[idx] || m.summary || '' }) }));

const rows = $('Attach Summaries').all().map(i=>i.json);
const week = $now.toFormat('LLL d, yyyy');
return rows.map((r,idx)=>({ json: {
  rank: String(idx+1), title: r.title||'', angle: r.blogAngle||'', driverType: r.driverType||'',
  clientRelevance: r.clientRelevance||'', score: String(r.marketDriverScore!=null?r.marketDriverScore:''),
  source: r.source||'', link: r.link||'', summary: r.summary2||r.summary||'', weekOf: week
}}));
